CoD.ZPauseSettings = CoD.ZPauseSettings or {}
CoD.ZPauseSettings.Locale = ZPauseLocaleAdapter.Create(
	ZPauseLocaleCore, ZPauseCatalogs, function () return Engine, Dvar end)

-- Visible sinks only. A dvar, a stored value, a page id or an owner token is
-- never passed through this.
CoD.ZPauseSettings.Text = function (key, fallback)
	if type(key) ~= "string" or key == "" then return fallback end
	local ok, said = pcall(CoD.ZPauseSettings.Locale.Text, key)
	if not ok or said == nil or said == key or said == "" then return fallback end
	return said
end

-- Named substitution, so a sentence built from another string is composed and
-- never concatenated in the catalog: a translation can reorder it or drop its
-- punctuation. Percent signs survive and inserted text is not parsed again.
CoD.ZPauseSettings.Format = function (key, fallback, values)
	local pattern = CoD.ZPauseSettings.Text(key, fallback)
	local ok, said = pcall(CoD.ZPauseSettings.Locale.Format, pattern, values)
	if not ok or type(said) ~= "string" or said == "" then return pattern end
	return said
end

