-- How many characters a string draws as, rather than bytes: a translated caption is UTF-8, and a
-- width chosen by byte count picks the small font for half of Russian.
CoD.ZPauseSettings.Length = function (value)
	local ok, n = pcall(CoD.ZPauseSettings.Locale.Length, value)
	if ok and type(n) == "number" then return n end
	return string.len(tostring(value or ""))
end

-- The English a key stands for, from the catalog every locale falls back to.
CoD.ZPauseSettings.Source = function (key)
	if type(key) ~= "string" or key == "" or type(ZPauseCatalogs.en) ~= "table" then return nil end
	return ZPauseCatalogs.en[key]
end

-- A key's translation, but only while the text it is asked about is still that key's English.
-- A row somebody re-worded - a CHANGED copy, a composed line - then draws its own words,
-- untranslated, rather than the translation of the row it was copied from.
CoD.ZPauseSettings.Words = function (key, english)
	if type(english) ~= "string" or english == "" then return english end
	if CoD.ZPauseSettings.Source(key) ~= english then return english end
	return CoD.ZPauseSettings.Text(key, english)
end

-- ZPause's provider in the shared registry, the kit's presentation ABI version 1:
-- B.Localizers.<owner> = { version = 1, text = function (english, context) }.
-- In a bundle ONE renderer draws every mod's rows, and this is the only way it reaches ZPause's
-- catalog; the shared kit's screen reads the same table. Registered from the data file so it is
-- there whichever renderer wins.
--
-- The English is matched by identity and never by position: the row's own key fields, then the
-- row's dvar family (setting., hint., choice.<dvar>.), then its tab, and last the English alone,
-- used only where exactly one key in the catalog holds it. Every match is an equality with the
-- catalog's English, so a copy whose labels were narrowed to its one current value cannot borrow
-- the first choice's translation - the index of a label is never trusted.
do
	local Z = CoD.ZPauseSettings
	local byDvar, byEnglish, shared = {}, {}, {}
	local en = type(ZPauseCatalogs.en) == "table" and ZPauseCatalogs.en or {}
	local key, english = next(en)
	while key ~= nil do
		local dvar = string.match(key, "^setting%.([^%.]+)$") or string.match(key, "^hint%.([^%.]+)$")
			or string.match(key, "^reason%.([^%.]+)$") or string.match(key, "^choice%.([^%.]+)%.")
		if dvar ~= nil then
			byDvar[dvar] = byDvar[dvar] or {}
			byDvar[dvar][english] = byDvar[dvar][english] or key
		end
		if shared[english] == nil then
			if byEnglish[english] == nil then
				byEnglish[english] = key
			elseif byEnglish[english] ~= key then
				byEnglish[english] = nil
				shared[english] = true
			end
		end
		key, english = next(en, key)
	end

	local function held(english, holder, fields)
		if type(holder) ~= "table" then return nil end
		for i = 1, #fields do
			local candidate = holder[fields[i]]
			if type(candidate) == "string" and Z.Source(candidate) == english then return candidate end
		end
		return nil
	end

	local function find(english, context)
		local row = type(context) == "table" and context.row or nil
		local tab = type(context) == "table" and context.tab or nil
		local found = held(english, row, { "labelKey", "hintKey", "boundaryKey", "scopeKey" })
		if found ~= nil then return found end
		if type(row) == "table" and type(row.choiceKeys) == "table" then
			for i = 1, #row.choiceKeys do
				if Z.Source(row.choiceKeys[i]) == english then return row.choiceKeys[i] end
			end
		end
		if type(row) == "table" and type(row.dvar) == "string" and byDvar[row.dvar] ~= nil then
			found = byDvar[row.dvar][english]
			if found ~= nil then return found end
		end
		found = held(english, tab, { "labelKey", "titleKey", "hintKey" })
		if found ~= nil then return found end
		return byEnglish[english]
	end

	CoD.ZBundleSettings = CoD.ZBundleSettings or {}
	CoD.ZBundleSettings.Localizers = CoD.ZBundleSettings.Localizers or {}
	CoD.ZBundleSettings.Localizers.zpause = {
		version = 1,
		text = function (english, context)
			if type(english) ~= "string" or english == "" then return english end
			local found = find(english, context)
			if found == nil then return english end
			return Z.Text(found, english)
		end
	}
end
-- ZP_LOCALE_END

